/// The `DimensionType$Skybox` enum — the vanilla string-representable
/// ("none" | "overworld" | "end") the client's sky pipeline gates on
/// (SkyRenderer.extractRenderState: NONE returns before ANY sky state,
/// END extracts only the end-flash triple and returns). The ABSENT
/// JSON key is the codec default OVERWORLD (optionalFieldOf — the
/// DimensionType bytecode).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Skybox {
    None,
    Overworld,
    End,
}

/// One built-in `minecraft:dimension_type` registry entry (the jar's
/// `data/minecraft/dimension_type/*.json`): world layout + environment.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct DimensionTypeDef {
    pub name: &'static str,
    pub min_y: i32,
    pub height: u32,
    pub logical_height: u32,
    pub has_skylight: bool,
    pub has_fixed_time: bool,
    pub ambient_light: f32,
    pub coordinate_scale: f64,
    pub timelines: Option<&'static str>,
    pub default_clock: Option<&'static str>,
    /// The lightmap's AmbientColor base (visual/ambient_light_color;
    /// the bytecode default black when the JSON states none).
    pub ambient_light_color: [u8; 3],
    /// The sky-pipeline gate (SkyRenderer.extractRenderState's skybox).
    pub skybox: Skybox,
    /// The STATED fog distances (blocks) — None when the JSON states
    /// none (the bytecode defaults' shape: start 0.0 / end 1024.0).
    pub fog_start_distance: Option<f32>,
    pub fog_end_distance: Option<f32>,
    /// The STATED cloud-fog end (blocks) — None when the JSON states
    /// none (the bytecode default 2048.0; no vanilla dimension
    /// declares it, the consumer's `visual/cloud_fog_end_distance`).
    pub cloud_fog_end_distance: Option<f32>,
    /// The STATED block-light tint — None when the JSON states
    /// none (the bytecode default -10100 = 0xFFFFD88C = #FFD88C,
    /// the warm torch cast; no vanilla dimension declares it, the
    /// consumer's `visual/block_light_tint`).
    pub block_light_tint: Option<[u8; 3]>,
    /// The STATED sky-light factor — None when the JSON states
    /// none (the bytecode default 1.0; no vanilla dimension
    /// declares it; the consumer multiplies it under the
    /// timeline's multiply track — the attribute-system fold).
    pub sky_light_factor: Option<f32>,
    /// The STATED sky-light color — None when the JSON states
    /// none (the bytecode default -1 = #FFFFFF white, the ARGB
    /// multiply identity); the real jar's end/nether state
    /// #ac60cd / #7a7aff. The consumer multiplies the stated
    /// base under the timeline's multiply track per channel,
    /// INTEGER arithmetic (javap ARGB.multiply).
    pub sky_light_color: Option<[u8; 3]>,
    /// The STATED night-vision color — None when the JSON states
    /// none (the bytecode default -6710887 = #999999 gray; no
    /// vanilla dimension declares it, the consumer's `visual/night_vision_color`). The shader consumes it under
    /// the night-vision FACTOR — the player's EFFECT state, not a
    /// timeline (zero without an effect; javap LightmapRenderStateExtractor).
    pub night_vision_color: Option<[u8; 3]>,
}

