/// Dimension type by registry id ("minecraft:overworld"), sorted for binary search.
pub fn dimension_type(name: &str) -> Option<&'static DimensionTypeDef> {
    DIMENSION_TYPES.binary_search_by_key(&name, |d| d.name).ok().map(|i| &DIMENSION_TYPES[i])
}

/// One built-in `minecraft:timeline` registry entry (the jar's
/// `data/minecraft/timeline/*.json`): keyframe tracks over a world clock.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct TimelineDef {
    pub name: &'static str,
    pub clock: &'static str,
    pub period_ticks: Option<i64>,
    pub tracks: usize,
    /// `minecraft:visual/sky_light_factor` keyframes, sorted by tick — the
    /// render track the lightmap's SkyFactor multiplies the sky term by
    /// (empty when the timeline carries no such track)
    pub sky_light_factor: &'static [(i64, f32)],
    /// `minecraft:visual/sky_light_color` keyframes, sorted by tick — the
    /// render track the lightmap's SkyLightColor multiplies the stated
    /// base by, per channel (empty when the timeline carries no such track)
    pub sky_light_color: &'static [(i64, [u8; 3])],
    /// `minecraft:gameplay/sky_light_level` keyframes, sorted by tick —
    /// the sky-light multiplier the gameplay side reads (empty when the
    /// timeline carries no such track)
    pub sky_light_level: &'static [(i64, f32)],
    /// `minecraft:gameplay/monsters_burn` keyframes, sorted by tick — the
    /// boolean hold track the sun-burn predicate gates on (empty when the
    /// timeline carries no such track)
    pub monsters_burn: &'static [(i64, bool)],
}

