/// Biome tag values by full tag id ("minecraft:is_forest").
pub fn biome_tag(name: &str) -> Option<&'static [&'static str]> {
    BIOME_TAGS.binary_search_by_key(&name, |t| t.0).ok().map(|i| BIOME_TAGS[i].1)
}
